(7622669, 1234939, 59740, '<td valign="top">Nice panorama but it''s hard to tell it''s abandoned.</td>', 'Nice panorama but it''s hard to tell it''s abandoned.', '2019-03-30 17:40:04.000000', NULL, 1),
(7622670, 1234393, 59740, '<td valign="top">The subject is fascinating but I would like to see more concentration on the building and not on the blurred foreground.</td>', 'The subject is fascinating but I would like to see more concentration on the building and not on the blurred foreground.', '2019-03-30 17:41:45.000000', NULL, 1),
(7622671, 1234850, 59740, '<td valign="top">Great building with terrific staircase but my attention is immediately drawn to the overexposed upper left corner. When I hold my hand over the open roof and bright highlights, the staircase pops.</td>', 'Great building with terrific staircase but my attention is immediately drawn to the overexposed upper left corner. When I hold my hand over the open roof and bright highlights, the staircase pops.', '2019-03-30 17:43:37.000000', NULL, 1),
(7622672, 1234954, 59740, '<td valign="top">What''s the subject? The building or the vegetation that occupies more than half of the frame. It would be nice to see a photo of just the building.</td>', 'What''s the subject? The building or the vegetation that occupies more than half of the frame. It would be nice to see a photo of just the building.', '2019-03-30 17:44:56.000000', NULL, 1),
(7622673, 1234898, 59740, '<td valign="top">It''s easy for me to criticize because I wasn''t there but this fantastic facade would look really great straight on rather than the angle you have taken. I know it may not have been possible.</td>', 'It''s easy for me to criticize because I wasn''t there but this fantastic facade would look really great straight on rather than the angle you have taken. I know it may not have been possible.', '2019-03-30 17:46:54.000000', NULL, 1),
(7622674, 1234578, 59740, '<td valign="top">Great subject. It''s too bad that much if the detail is lost in the overexposed highlights and black shadows.</td>', 'Great subject. It''s too bad that much if the detail is lost in the overexposed highlights and black shadows.', '2019-03-30 17:47:49.000000', NULL, 1),
(7622675, 1234938, 59740, '<td valign="top">This looks like a great old farm building but it''s hard to tell because it''s so far away.</td>', 'This looks like a great old farm building but it''s hard to tell because it''s so far away.', '2019-03-30 17:48:41.000000', NULL, 1),
(7622676, 1234956, 59740, '<td valign="top">Great exposure. Was it HDR or flash? My only change would be to crop some off the left side up to the window. Nice photo.</td>', 'Great exposure. Was it HDR or flash? My only change would be to crop some off the left side up to the window. Nice photo.', '2019-03-30 17:49:47.000000', NULL, 1),
(7622677, 1234520, 59740, '<td valign="top">Nice old building but a lot is lost in the totally black shadows.</td>', 'Nice old building but a lot is lost in the totally black shadows.', '2019-03-30 17:50:33.000000', NULL, 1),
(7622678, 1234947, 59740, '<td valign="top">To my eye this looks over-sharpened.</td>', 'To my eye this looks over-sharpened.', '2019-03-30 17:51:19.000000', NULL, 1),
(7622679, 1234495, 59740, '<td valign="top">I''m not sure if it fits the category since I can''t tell that the building is abandoned but I love it anyway. If I were the maker I would try to tone down the bright highlights. Very nice shot!</td>', 'I''m not sure if it fits the category since I can''t tell that the building is abandoned but I love it anyway. If I were the maker I would try to tone down the bright highlights. Very nice shot!', '2019-03-30 17:52:55.000000', NULL, 1),
(7622680, 1234957, 59740, '<td valign="top">Is this the "Bates" house? Creepy looking. My only problem with it is that the focus is on the detail at the top with most of the building being blurred.</td>', 'Is this the "Bates" house? Creepy looking. My only problem with it is that the focus is on the detail at the top with most of the building being blurred.', '2019-03-30 17:54:59.000000', NULL, 1),
(7622681, 1234906, 59740, '<td valign="top">Nice but doesn''t seem abandoned. Someone is taking care of all those plants.</td>', 'Nice but doesn''t seem abandoned. Someone is taking care of all those plants.', '2019-03-30 17:55:45.000000', NULL, 1),
