(7622686, 1234944, 59740, '<td valign="top">The vignetting adds to the composition, but I''m not sure if that is allowed in standard editing. I like it anyway.</td>', 'The vignetting adds to the composition, but I''m not sure if that is allowed in standard editing. I like it anyway.', '2019-03-30 18:01:48.000000', NULL, 1),
(7622687, 1234916, 59740, '<td valign="top">The building is too far away to see much detail. Nice scene but IMO it doesn''t emphasize the buiding enough.</td>', 'The building is too far away to see much detail. Nice scene but IMO it doesn''t emphasize the buiding enough.', '2019-03-30 18:03:13.000000', NULL, 1),
