(7623457, 1234850, 153275, '<td valign="top">Nice shot, it really shows the decay of what once must have been a grand stairway with woodcut details. I like the moss on the bricks also.</td>', 'Nice shot, it really shows the decay of what once must have been a grand stairway with woodcut details. I like the moss on the bricks also.', '2019-04-03 13:31:44.000000', NULL, 1),
(7623461, 1234941, 153275, '<td valign="top">Nice shot, there is so much to see. I like the light on the building, making it look so bright against the dark sky.<br/>The graffiti artist who did the blue lettering was definitely nut suffering from fear of heights...</td>', 'Nice shot, there is so much to see. I like the light on the building, making it look so bright against the dark sky.The graffiti artist who did the blue lettering was definitely nut suffering from fear of heights...', '2019-04-03 15:48:41.000000', NULL, 1),
(7623462, 1234900, 153275, '<td valign="top">Nice perspective. Love the texture of the brick walls.</td>', 'Nice perspective. Love the texture of the brick walls.', '2019-04-03 15:49:40.000000', NULL, 1),
(7623463, 1234495, 153275, '<td valign="top">Must be spectacular staying there... I dont think my wife will join me though.</td>', 'Must be spectacular staying there... I dont think my wife will join me though.', '2019-04-03 15:52:09.000000', NULL, 1),
(7623464, 1234927, 153275, '<td valign="top">That sky is really dramatic... looks like it contains some brown color (unless its my screen settings)</td>', 'That sky is really dramatic... looks like it contains some brown color (unless its my screen settings)', '2019-04-03 15:53:37.000000', NULL, 1),
