(7623518, 1234933, 114285, '<td valign="top">This one begs to be in black and white due to the flat coloring. Otherwise it meets the challenge well enough.</td>', 'This one begs to be in black and white due to the flat coloring. Otherwise it meets the challenge well enough.', '2019-04-04 02:38:24.000000', NULL, 1),
